def parse_and_download_assets(data_string, download_files=False):
    pattern = r"((?:chains|logo)/[\w\-\./]+\.(?:svg|png|webp))([0-9]{10,})"
    matches = re.findall(pattern, data_string)

    assets = []
    seen = set()

    for path, timestamp in matches:
        if path not in seen:
            seen.add(path)
            full_url = f"https://assets.sentio.xyz/{path}"
            assets.append({"path": path, "url": full_url})

    print(f"Found {len(assets)} unique assets.")

    if download_files:
        os.makedirs("downloaded_assets", exist_ok=True)
        for item in assets:
            file_path = item["path"]
            url = item["url"]
            local_path = os.path.join("downloaded_assets", file_path)

            os.makedirs(os.path.dirname(local_path), exist_ok=True)

            try:
                response = requests.get(url, timeout=10)
                if response.status_code == 200:
                    with open(local_path, "wb") as f:
                        f.write(response.content)
                    print(f"Downloaded: {file_path}")
                else:
                    print(f"Failed to download {file_path}: Status {response.status_code}")
            except Exception as e:
                print(f"Error downloading {file_path}: {e}")

    return assets

if __name__ == "__main__":
    extracted_assets = parse_and_download_assets(raw_data, download_files=True)
    for asset in extracted_assets[:5]:
        print(asset)
